 "content": "def transform(grid):
    """Expand the diagonal color motif into a periodic diagonal tiling."""
    height, width = len(grid), len(grid[0])
    stripes = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                offset = c - r
                if offset in stripes and stripes[offset] != color:
                    raise ValueError("inconsistent colors on one diagonal")
                stripes[offset] = color

    period = len(stripes)
    if period == 0:
        return [[0] * width for _ in range(height)]

    motif = {}
    for offset, color in stripes.items():
        residue = offset % period
        if residue in motif and motif[residue] != color:
            raise ValueError("inconsistent diagonal motif")
        motif[residue] = color

    # Missing residue classes are only possible for degenerate motifs; extend
    # the nearest observed class cyclically.
    for residue in range(period):
        if residue not in motif:
            nearest = min(motif, key=lambda k: min((residue-k) % period, (k-residue) % period))
            motif[residue] = motif[nearest]

    return [[motif[(c-r) % period] for c in range(width)] for r in range(height)]


